// IMPOSTER — Calculate Price

const a3Quantity = Number($json.a3_quantity || 0);
const a4Quantity = Number($json.a4_quantity || 0);

// Pricing rules
const A3_SINGLE_PRICE = 60;
const A3_PACK_QUANTITY = 5;
const A3_PACK_PRICE = 250;

const A4_SINGLE_PRICE = 40;
const A4_PACK_QUANTITY = 5;
const A4_PACK_PRICE = 170;

// Calculate price for a size
function calculatePrice(quantity, packQuantity, packPrice, singlePrice) {
  if (quantity <= 0) return 0;

  const packs = Math.floor(quantity / packQuantity);
  const remaining = quantity % packQuantity;

  return (packs * packPrice) + (remaining * singlePrice);
}

const a3Price = calculatePrice(
  a3Quantity,
  A3_PACK_QUANTITY,
  A3_PACK_PRICE,
  A3_SINGLE_PRICE
);

const a4Price = calculatePrice(
  a4Quantity,
  A4_PACK_QUANTITY,
  A4_PACK_PRICE,
  A4_SINGLE_PRICE
);

const totalPrice = a3Price + a4Price;

return {
  json: {
    ...$json,

    a3_price: a3Price,
    a4_price: a4Price,
    total_price: totalPrice,

    currency: "INR"
  }
};

// ============================================================
// IMPOSTER — NORMALIZE ORDER
// ============================================================
// Converts the raw Google Form / Google Sheets response into
// one clean order object.
//
// Handles:
//   1. A3 only
//   2. A4 only
//   3. Both A3 + A4
//
// Handles design choices:
//   - Own image
//   - IMPOSTER Catalog
//   - Catalog + own image
// ============================================================


const data = $json;


// ============================================================
// HELPER FUNCTIONS
// ============================================================

function cleanString(value) {
  if (value === undefined || value === null) {
    return "";
  }

  return String(value).trim();
}


// Return the first non-empty value from a list of possible
// Google Sheets column names.
function firstValue(...values) {
  for (const value of values) {
    const cleaned = cleanString(value);

    if (cleaned !== "") {
      return cleaned;
    }
  }

  return "";
}


// Parse quantity safely.
function parseQuantity(value) {

  if (
    value === undefined ||
    value === null ||
    cleanString(value) === ""
  ) {
    return 0;
  }

  const quantity = Number(value);

  if (!Number.isFinite(quantity) || quantity < 0) {
    return 0;
  }

  return Math.floor(quantity);
}


// Parse catalog numbers.
//
// Examples:
// "22"       -> [22]
// "22,34"    -> [22,34]
// "22, 34"   -> [22,34]
//
// Only numbers 1–120 are accepted.
function parseCatalogNumbers(value) {

  const text = cleanString(value);

  if (!text) {
    return [];
  }

  // Google Sheets turns a list like "104,126,134,168,169" into the single number
  // 104126134168169. Split such digit-only values back into groups of 3 from the right.
  if (/^\d{4,}$/.test(text)) {
    const groups = [];
    let s = text;
    while (s.length > 3) { groups.unshift(s.slice(-3)); s = s.slice(0, -3); }
    if (s) groups.unshift(s);
    return groups.map(Number).filter(x => Number.isInteger(x) && x >= 1);
  }

  // Accept commas, spaces, semicolons, "and" etc. as separators.
  // No upper limit here: "Validate Catalog" reports numbers that
  // are not in the Catalog sheet (clearer than silently dropping them).
  return text
    .split(/[^0-9]+/)
    .filter(x => x !== "")
    .map(x => Number(x))
    .filter(x => Number.isInteger(x) && x >= 1);
}


// ============================================================
// CUSTOMER INFORMATION
// ============================================================

const customerName = cleanString(
  data["Full Name"]
);

const email = cleanString(
  data["Email Address"]
);

const whatsapp = cleanString(
  data["WhatsApp Number"]
);

const branch = cleanString(
  data["Branch"]
);

const year = cleanString(
  data["Year"]
);

const hostel = cleanString(
  data["Please select your hostel from the list below:"]
);


// ============================================================
// POSTER SIZE
// ============================================================

const posterSize = cleanString(
  data["Poster Size"]
);


// ============================================================
// A3 QUANTITY
// ============================================================
//
// A3-only form uses:
//
// How many A3 posters do you want?
//
// Both A3 + A4 section uses:
//
// A3+A4 — How many A3 posters do you want?
//
// We check both.
// ============================================================

const a3Quantity = parseQuantity(
  firstValue(
    data["A3+A4 — How many A3 posters do you want?"],
    data["A3+A4 — How many A3 posters do you want? "],
    data["How many A3 posters do you want?"]
  )
);


// ============================================================
// A4 QUANTITY
// ============================================================
//
// A4-only form uses:
//
// How many A4 posters do you want?
//
// Both section uses:
//
// A3+A4 — How many A4 posters do you want?
// ============================================================

const a4Quantity = parseQuantity(
  firstValue(
    data["A3+A4 — How many A4 posters do you want?"],
    data["A3+A4 — How many A4 posters do you want? "],
    data["How many A4 posters do you want?"]
  )
);


// ============================================================
// A3 DESIGN SOURCE
// ============================================================

const a3Source = firstValue(

  // Both A3 + A4 section
  data["A3+A4 — How would you like to choose A3 design?"],
  data["A3+A4 — How would you like to choose your A3 design?"],

  // A3-only section
  data["How would you like to choose your A3 design?"]

);


// ============================================================
// A4 DESIGN SOURCE
// ============================================================

const a4Source = firstValue(

  // Both A3 + A4 section
  data["A3+A4 — How would you like to choose A4 design?"],
  data["A3+A4 — How would you like to choose your A4 design?"],

  // A4-only section
  data["How would you like to choose your A4 design?"]

);


// ============================================================
// A3 CATALOG NUMBERS
// ============================================================

const a3CatalogRaw = firstValue(

  // Both section
  data["A3+A4 — A3 Catalog Design Number(s)\n👉 OPEN CATALOG"],
  data["A3+A4 — A3 Catalog Design Number(s) 👉 OPEN CATALOG"],
  data["A3+A4 — A3 Catalog Design Number(s)"],

  // A3-only section
  data["A3 Catalog Design Number(s)\n👉 OPEN CATALOG"],
  data["A3 Catalog Design Number(s) 👉 OPEN CATALOG"],
  data["A3 Catalog Design Number(s)"]

);

const a3CatalogNumbers =
  parseCatalogNumbers(a3CatalogRaw);


// ============================================================
// A4 CATALOG NUMBERS
// ============================================================

const a4CatalogRaw = firstValue(

  // Both section
  data["A3+A4 — A4 Catalog Design Number(s)\n👉 OPEN CATALOG"],
  data["A3+A4 — A4 Catalog Design Number(s) 👉 OPEN CATALOG"],
  data["A3+A4 — A4 Catalog Design Number(s)"],

  // A4-only section
  data["A4 Catalog Design Number(s)\n👉 OPEN CATALOG"],
  data["A4 Catalog Design Number(s) 👉 OPEN CATALOG"],
  data["A4 Catalog Design Number(s)"],

  // Older generic Form column (used by A4-only orders)
  data["If you selected a design from the IMPOSTER Catalog, enter the PDF/Image Number below.\n\n"],
  data["If you selected a design from the IMPOSTER Catalog, enter the PDF/Image Number below."]

);

const a4CatalogNumbers =
  parseCatalogNumbers(a4CatalogRaw);


// ============================================================
// CUSTOM A3 FILE
// ============================================================
//
// A3-only section:
//
// Upload your own A3 design
//
// Both section:
//
// A3+A4 — Upload your own A3 design
//
// We also check the generic Google Form upload question as a
// fallback.
// ============================================================

const a3CustomFile = firstValue(

  // Both A3 + A4
  data["A3+A4 — Upload your own A3 design"],
  data["A3+A4 — Upload your own A3 design "],

  // A3-only
  data["Upload your own A3 design"],

  // Generic upload column belongs to the A4-only form
  (a4Quantity === 0 ? data["Please upload the image you would like us to print for your poster:"] : "")

);


// ============================================================
// CUSTOM A4 FILE
// ============================================================
//
// A4-only form uses the generic upload question:
//
// Please upload the image you would like us to print for your poster:
//
// We also check possible A4-specific / Both-section names.
// ============================================================

const a4CustomFile = firstValue(

  // Both A3 + A4
  data["A3+A4 — Upload your own A4 design"],
  data["A3+A4 — Upload your own A4 design "],

  // A4-specific name, if present
  data["Upload your own A4 design"],

  // Generic upload column (A4-only form); never for A3-only orders
  (a3Quantity === 0 ? data["Please upload the image you would like us to print for your poster:"] : "")

);


// ============================================================
// IMPORTANT CUSTOM FILE CORRECTION FOR BOTH ORDERS
// ============================================================
//
// Google Forms can produce duplicate/generic upload columns.
//
// For a Both order, if the A3+A4-specific A3/A4 fields exist,
// use those first.
//
// The previous firstValue() logic already handles this.
// ============================================================


// ============================================================
// PAYMENT
// ============================================================

const paymentMode = firstValue(

  data[
    "Payment Mode\n(Once your payment is completed, you will receive a WhatsApp confirmation message from the IMPOSTER team confirming your order.\nPlease make sure the WhatsApp number provided in the form is correct so we can contact you without any issues.)"
  ],

  data["Payment Mode"]

);


const paymentScreenshot = firstValue(

  data[" Payment Screenshot\n"],

  data["Payment Screenshot"],

  data[" Payment Screenshot"]

);


// ============================================================
// VALIDATION
// ============================================================

const errors = [];


// ============================================================
// 1. POSTER SIZE / QUANTITY
// ============================================================

if (
  posterSize === "A3" &&
  a3Quantity < 1
) {

  errors.push(
    "A3 selected but A3 quantity is missing."
  );

}


if (
  posterSize === "A4" &&
  a4Quantity < 1
) {

  errors.push(
    "A4 selected but A4 quantity is missing."
  );

}


if (
  posterSize === "Both A3 and A4"
) {

  if (a3Quantity < 1) {

    errors.push(
      "Both selected but A3 quantity is missing."
    );

  }


  if (a4Quantity < 1) {

    errors.push(
      "Both selected but A4 quantity is missing."
    );

  }

}


// ============================================================
// 2. CUSTOM DESIGN COUNTS
// ============================================================
//
// One uploaded custom file = one custom design.
//
// Multiple comma-separated uploaded files = multiple designs.
//
// ============================================================

function countUrls(urlStr) {

  if (!urlStr) return 0;

  return urlStr
    .split(",")
    .map(s => s.trim())
    .filter(s => s !== "")
    .length;
}

const a3CustomCount = countUrls(a3CustomFile);
const a4CustomCount = countUrls(a4CustomFile);


// ============================================================
// 3. TOTAL DESIGN COUNTS
// ============================================================

const a3DesignCount =
  a3CatalogNumbers.length +
  a3CustomCount;

const a4DesignCount =
  a4CatalogNumbers.length +
  a4CustomCount;


// ============================================================
// 4. QUANTITY VS DESIGN VALIDATION
// ============================================================

if (a3Quantity > 0) {

  if (a3DesignCount !== a3Quantity) {

    errors.push(
      `A3 quantity is ${a3Quantity}, but ${a3DesignCount} design(s) were provided.`
    );

  }

}


if (a4Quantity > 0) {

  if (a4DesignCount !== a4Quantity) {

    errors.push(
      `A4 quantity is ${a4Quantity}, but ${a4DesignCount} design(s) were provided.`
    );

  }

}


// ============================================================
// 5. DESIGN-SOURCE VALIDATION
// ============================================================
//
// This catches cases such as:
//
// "Catalog" selected but no catalog number
//
// or
//
// "My own image" selected but no upload.
//
// ============================================================

function sourceContains(source, text) {

  return source
    .toLowerCase()
    .includes(text.toLowerCase());

}


// ---------- A3 ----------

if (a3Quantity > 0) {

  if (
    sourceContains(a3Source, "catalog") &&
    a3CatalogNumbers.length === 0
  ) {

    errors.push(
      "A3 catalog was selected but no valid catalog design number was provided."
    );

  }


  if (
    sourceContains(a3Source, "own image") &&
    a3CustomCount === 0
  ) {

    errors.push(
      "A3 own image was selected but no custom image was uploaded."
    );

  }

}


// ---------- A4 ----------

if (a4Quantity > 0) {

  if (
    sourceContains(a4Source, "catalog") &&
    a4CatalogNumbers.length === 0
  ) {

    errors.push(
      "A4 catalog was selected but no valid catalog design number was provided."
    );

  }


  if (
    sourceContains(a4Source, "own image") &&
    a4CustomCount === 0
  ) {

    errors.push(
      "A4 own image was selected but no custom image was uploaded."
    );

  }

}


// ============================================================
// FINAL VALIDITY
// ============================================================

const isValid =
  errors.length === 0;


// ============================================================
// RETURN NORMALIZED ORDER
// ============================================================

return {

  json: {

    // --------------------------------------------------------
    // SUBMISSION
    // --------------------------------------------------------

    submitted_at:
      cleanString(data["Timestamp"]),


    // --------------------------------------------------------
    // CUSTOMER
    // --------------------------------------------------------

    customer_name:
      customerName,

    email:
      email,

    whatsapp:
      whatsapp,

    branch:
      branch,

    year:
      year,

    hostel:
      hostel,


    // --------------------------------------------------------
    // ORDER
    // --------------------------------------------------------

    poster_size:
      posterSize,


    // --------------------------------------------------------
    // A3
    // --------------------------------------------------------

    a3_quantity:
      a3Quantity,

    a3_source:
      a3Source,

    a3_catalog_numbers:
      a3CatalogNumbers,

    a3_custom_file:
      a3CustomFile,


    // --------------------------------------------------------
    // A4
    // --------------------------------------------------------

    a4_quantity:
      a4Quantity,

    a4_source:
      a4Source,

    a4_catalog_numbers:
      a4CatalogNumbers,

    a4_custom_file:
      a4CustomFile,


    // --------------------------------------------------------
    // COUNTS
    // --------------------------------------------------------

    a3_catalog_count:
      a3CatalogNumbers.length,

    a3_custom_count:
      a3CustomCount,

    a4_catalog_count:
      a4CatalogNumbers.length,

    a4_custom_count:
      a4CustomCount,


    // --------------------------------------------------------
    // PAYMENT
    // --------------------------------------------------------

    payment_mode:
      paymentMode,

    payment_screenshot:
      paymentScreenshot,


    // --------------------------------------------------------
    // VALIDATION
    // --------------------------------------------------------

    is_valid:
      isValid,

    validation_errors:
      errors,


    // --------------------------------------------------------
    // INITIAL STATUS
    // --------------------------------------------------------

    payment_status:
      "PENDING",

    design_status:
      "WAITING",

    print_status:
      "NOT_READY",

    whatsapp_status:
      "NOT_SENT",

    order_status:
      "NEW"

  }

};

// IMPOSTER — Generate Production-Safe Order ID

const now = new Date();

// India date/time
const indiaTime = new Intl.DateTimeFormat("en-IN", {
  timeZone: "Asia/Kolkata",
  year: "2-digit",
  month: "2-digit",
  day: "2-digit",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hour12: false
}).formatToParts(now);

const parts = {};

for (const part of indiaTime) {
  if (part.type !== "literal") {
    parts[part.type] = part.value;
  }
}

const dateCode =
  parts.year +
  parts.month +
  parts.day;

const timeCode =
  parts.hour +
  parts.minute +
  parts.second;

// Use the n8n execution ID plus the current item's data
// to create a unique suffix for this order.
const executionId = String($execution.id || "");

const sourceTimestamp = String($json.submitted_at || "");
const customerEmail = String($json.email || "");
const whatsapp = String($json.whatsapp || "");

// Build a deterministic per-order source string.
const source = [
  executionId,
  sourceTimestamp,
  customerEmail,
  whatsapp
].join("|");

// Create a compact hash from the source string.
let hash = 0;

for (let i = 0; i < source.length; i++) {
  hash = ((hash << 5) - hash) + source.charCodeAt(i);
  hash |= 0;
}

const suffix = Math.abs(hash).toString(36).toUpperCase().padStart(6, "0");

// Final Order ID
const orderId = `IMP-${dateCode}-${timeCode}-${suffix}`;

return {
  json: {
    ...$json,

    order_id: orderId,
    order_created_at: now.toISOString()
  }
};

// IMPOSTER — Validate Catalog
// Current architecture:
// - Loop Over Items processes ONE order at a time.
// - Get Catalog provides the 50 catalog rows.
// - This node validates the CURRENT order only.
// - Output must always be ONE order item.

const catalogItems = $input.all();

// Get the current order being processed by the loop.
// Generate Order ID belongs to the current loop iteration.
const order = $('Generate Order ID').item.json;

if (!order) {
  throw new Error("No current order found from Generate Order ID.");
}

// Build catalog lookup.
const catalogMap = new Map();

for (const item of catalogItems) {
  const row = item.json;

  const designNo = Number(row["Design No"]);
  const canvaPage = Number(row["Canva Page"]);
  const active = String(row["Active"] || "").trim().toUpperCase();
  const driveFileId = String(row["Drive File ID"] || "").trim();

  if (!Number.isInteger(designNo)) {
    continue;
  }

  catalogMap.set(designNo, {
    design_no: designNo,
    canva_page: canvaPage,
    active,
    drive_file_id: driveFileId
  });
}

// Validate requested catalog numbers for one size.
function validateCatalogNumbers(numbers, size) {
  const valid = [];
  const invalid = [];
  const inactive = [];
  const missingFileId = [];

  for (const rawNumber of numbers || []) {
    const number = Number(rawNumber);

    const entry = catalogMap.get(number);

    if (!entry) {
      invalid.push(number);
      continue;
    }

    if (entry.active !== "YES") {
      inactive.push(number);
      continue;
    }

    if (!entry.drive_file_id) {
      missingFileId.push(number);
      continue;
    }

    valid.push({
      design_no: entry.design_no,
      canva_page: entry.canva_page,
      drive_file_id: entry.drive_file_id
    });
  }

  return {
    size,
    requested: numbers || [],
    valid,
    invalid,
    inactive,
    missing_file_id: missingFileId,
    is_valid:
      invalid.length === 0 &&
      inactive.length === 0 &&
      missingFileId.length === 0
  };
}

// Validate the CURRENT order only.
const a3Validation = validateCatalogNumbers(
  order.a3_catalog_numbers,
  "A3"
);

const a4Validation = validateCatalogNumbers(
  order.a4_catalog_numbers,
  "A4"
);

// Collect catalog errors.
const errors = [];

if (a3Validation.invalid.length > 0) {
  errors.push(
    `Invalid A3 catalog number(s): ${a3Validation.invalid.join(", ")}`
  );
}

if (a3Validation.inactive.length > 0) {
  errors.push(
    `Inactive A3 catalog number(s): ${a3Validation.inactive.join(", ")}`
  );
}

if (a3Validation.missing_file_id.length > 0) {
  errors.push(
    `Missing A3 Drive File ID(s): ${a3Validation.missing_file_id.join(", ")}`
  );
}

if (a4Validation.invalid.length > 0) {
  errors.push(
    `Invalid A4 catalog number(s): ${a4Validation.invalid.join(", ")}`
  );
}

if (a4Validation.inactive.length > 0) {
  errors.push(
    `Inactive A4 catalog number(s): ${a4Validation.inactive.join(", ")}`
  );
}

if (a4Validation.missing_file_id.length > 0) {
  errors.push(
    `Missing A4 Drive File ID(s): ${a4Validation.missing_file_id.join(", ")}`
  );
}

// Extract Drive File IDs while preserving duplicates.
const a3_catalog_drive_file_ids =
  a3Validation.valid.map(x => x.drive_file_id);

const a4_catalog_drive_file_ids =
  a4Validation.valid.map(x => x.drive_file_id);

// Return EXACTLY ONE order.
return [
  {
    json: {
      ...order,

      a3_catalog_validation: a3Validation,
      a4_catalog_validation: a4Validation,

      a3_catalog_pages:
        a3Validation.valid.map(x => x.canva_page),

      a4_catalog_pages:
        a4Validation.valid.map(x => x.canva_page),

      a3_catalog_drive_file_ids,
      a4_catalog_drive_file_ids,

      catalog_validation: {
        is_valid: errors.length === 0,
        errors
      },

      catalog_status:
        errors.length === 0 ? "VALID" : "ERROR"
    }
  }
];

// IMPOSTER — Prepare Order Record
// One loop iteration = one order.
// Validate Catalog returns exactly one validated order item.

const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `SAFETY STOP: Prepare Order Record expected exactly 1 item, received ${items.length}.`
  );
}

const order = items[0].json;

// Combine form-level and catalog-level validation problems.
const problems = [
  ...(order.validation_errors || []),
  ...(((order.catalog_validation || {}).errors) || [])
];
const orderValid = problems.length === 0;

return [
  {
    json: {
      order_id: order.order_id,
      created_at: order.order_created_at,

      customer_name: order.customer_name,
      email: order.email,
      whatsapp: order.whatsapp,
      branch: order.branch,
      year: order.year,
      hostel: order.hostel,

      poster_size: order.poster_size,

      a3_quantity: order.a3_quantity,
      a3_source: order.a3_source,
      a3_catalog_numbers:
        (order.a3_catalog_numbers || []).join(", "),
      a3_custom_file: order.a3_custom_file,

      a4_quantity: order.a4_quantity,
      a4_source: order.a4_source,
      a4_catalog_numbers:
        (order.a4_catalog_numbers || []).join(", "),
      a4_custom_file: order.a4_custom_file,

      a3_price: order.a3_price,
      a4_price: order.a4_price,
      total_price: order.total_price,

      payment_mode: order.payment_mode,
      payment_screenshot: order.payment_screenshot,

      payment_status: order.payment_status,
      design_status: orderValid ? "UPSCALING" : "ON HOLD",

      canva_a3: "",
      canva_a4: "",

      print_status: order.print_status,
      whatsapp_status: order.whatsapp_status,
      order_status: orderValid ? order.order_status : "NEEDS FIXING",

      notes: orderValid ? "" : "ORDER NEEDS FIXING: " + problems.join(" | "),

      order_valid: orderValid
    }
  }
];

// IMPOSTER — Build Catalog Index

const files = $input.all();
const output = [];

for (const item of files) {
  const file = item.json;
  const fileName = String(file.name || "").trim();

  // Only process PNG files with a numeric filename.
  const match = fileName.match(/^(\d+)\.png$/i);

  if (!match) {
    continue;
  }

  const designNo = Number(match[1]);

  // Update limit: Designs 1–120 are valid.
  if (designNo < 1 || designNo > 120) {
    continue;
  }

  output.push({
    json: {
      design_no: designNo,
      canva_page: designNo,
      active: "YES",
      drive_file_id: file.id,
      file_name: fileName
    }
  });
}

// Sort by Design Number
output.sort((a, b) => a.json.design_no - b.json.design_no);

return output;

// Build the list of images that must be upscaled for this order.
// One job = one poster file. Catalog designs + customer uploads, per size.
const v = $('Validate Catalog').first().json;

function driveIds(text) {
  if (!text) return [];
  const ids = [];
  for (const part of String(text).split(',')) {
    const t = part.trim();
    const m = t.match(/[?&]id=([a-zA-Z0-9_-]+)/) || t.match(/\/d\/([a-zA-Z0-9_-]+)/);
    if (m) ids.push(m[1]);
  }
  return ids;
}

const finalFolders = {
  A3: $('Create FINAL A3 Folder').first().json.id,
  A4: $('Create FINAL A4 Folder').first().json.id
};

const jobs = [];
for (const size of ['A3', 'A4']) {
  const s = size.toLowerCase();
  if (!(Number(v[`${s}_quantity`]) > 0)) continue;   // size not ordered
  let n = 0;
  const catalogNos = v[`${s}_catalog_numbers`] || [];
  (v[`${s}_catalog_drive_file_ids`] || []).forEach((id, i) => {
    n++;
    jobs.push({ size, kind: 'catalog', label: `C${catalogNos[i] ?? n}`, n, file_id: id });
  });
  driveIds(v[`${s}_custom_file`]).forEach(id => {
    n++;
    jobs.push({ size, kind: 'custom', label: `U${n}`, n, file_id: id });
  });
}

return [{
  json: {
    order_id: v.order_id,
    customer_name: v.customer_name,
    final_folders: finalFolders,
    jobs
  }
}];
